INSERT [dbo].[exam_questions] ([id], [exam_id], [question_id], [position], [snapshot]) VALUES (18, 3, 26, 4, N''{"id":26,"title":"[TEST] K01 - Giá trị lớn nhất của hàm lượng giác 19","content":"<p>Tìm giá trị lớn nhất của y = 21 sin x + 4. Trình bày các bước giải.</p>","chapter":"Chương 1 – Hàm số lượng giác","topic":"Hàm số lượng giác","type":"ESSAY","difficulty":"EASY","cognitiveLevel":"KNOWLEDGE","answer":"Vì -1 ≤ sin x ≤ 1 và 21 &gt; 0, giá trị lớn nhất là 21 + 4 = 25.","courseId":2,"published":true}'')
