INSERT [dbo].[exam_questions] ([id], [exam_id], [question_id], [position], [snapshot]) VALUES (138, 21, 170, 4, N''{"id":170,"title":"[TEST] K07 - Giá trị lớn nhất của hàm lượng giác 19","content":"<p>Tìm giá trị lớn nhất của y = 27 sin x + 4. Trình bày các bước giải.</p>","chapter":"Chương 1 – Hàm số lượng giác","topic":"Hàm số lượng giác","type":"ESSAY","difficulty":"EASY","cognitiveLevel":"KNOWLEDGE","answer":"Vì -1 ≤ sin x ≤ 1 và 27 &gt; 0, giá trị lớn nhất là 27 + 4 = 31.","courseId":8,"published":true}'')
INSERT [dbo].[exam_questions] ([id], [exam_id], [question_id], [position], [snapshot]) VALUES (139, 21, 171, 5, N''{"id":171,"title":"[TEST] K07 - Số hạng của cấp số cộng 20","content":"<p>Cấp số cộng có u₁ = 28, công sai d = 5. Tính u9. Trình bày các bước giải.</p>","chapter":"Chương 2 – Dãy số","topic":"Cấp số cộng","type":"ESSAY","difficulty":"EASY","cognitiveLevel":"KNOWLEDGE","answer":"uₙ = u₁ + (n-1)d, nên u9 = 28 + 8 × 5 = 68.","courseId":8,"published":true}'')
INSERT [dbo].[exam_questions] ([id], [exam_id], [question_id], [position], [snapshot]) VALUES (140, 22, 162, 0, N''{"id":162,"title":"[TEST] K07 - Đếm đường thẳng trong mặt phẳng 11","content":"<p>Cho 5 điểm trong một mặt phẳng, không có ba điểm thẳng hàng. Có bao nhiêu đường thẳng đi qua các cặp điểm?</p>","chapter":"Chương 4 – Đường thẳng và mặt phẳng","topic":"Đường thẳng và mặt phẳng trong không gian","type":"MCQ","difficulty":"MEDIUM","cognitiveLevel":"UNDERSTANDING","answer":"10","courseId":8,"published":true,"options":["11","12","9","10"]}'')
