    EXEC @ExecuteInTarget N'SET IDENTITY_INSERT [dbo].[lessons] ON 

INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (1, 1, 1, 2, N''Hàm số lượng giác'', N''Kiến thức trọng tâm và ví dụ Toán 11.'', N''Nắm được định nghĩa, công thức và vận dụng giải bài tập.'', N''<h2>Hàm số y = sin x và y = cos x</h2><p>Tập xác định: ℝ. Tập giá trị: [−1;1]. Chu kỳ: 2π.</p><p>Hàm sin là hàm lẻ; hàm cos là hàm chẵn.</p><h2>Ví dụ</h2><p>Với y = 2 sin x + 1, giá trị nhỏ nhất là −1 và lớn nhất là 3.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2), CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (2, 1, 2, 2, N''Cấp số cộng'', N''Kiến thức trọng tâm và ví dụ Toán 11.'', N''Nắm được định nghĩa, công thức và vận dụng giải bài tập.'', N''<h2>Cấp số cộng</h2><p>uₙ = u₁ + (n−1)d. Tổng n số hạng: Sₙ = n(u₁ + uₙ)/2.</p><p>Ví dụ: u₁=2, d=3 thì u₁₀=29.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2), CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (3, 1, 3, 2, N''Giới hạn của dãy số'', N''Kiến thức trọng tâm và ví dụ Toán 11.'', N''Nắm được định nghĩa, công thức và vận dụng giải bài tập.'', N''<h2>Giới hạn hữu hạn</h2><p>Nếu uₙ tiến tới L khi n tăng vô hạn, viết lim uₙ = L.</p><p>Ví dụ: (3n+1)/n = 3+1/n nên giới hạn bằng 3.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2), CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (4, 1, 4, 2, N''Đường thẳng và mặt phẳng'', N''Kiến thức trọng tâm và ví dụ Toán 11.'', N''Nắm được định nghĩa, công thức và vận dụng giải bài tập.'', N''<h2>Các tính chất thừa nhận</h2><p>Qua ba điểm không thẳng hàng xác định duy nhất một mặt phẳng.</p><p>Nếu hai điểm phân biệt của một đường thẳng thuộc mặt phẳng thì đường thẳng nằm trong mặt phẳng đó.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2), CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (5, 1, 5, 2, N''Quan hệ song song'', N''Kiến thức trọng tâm và ví dụ Toán 11.'', N''Nắm được định nghĩa, công thức và vận dụng giải bài tập.'', N''<h2>Hai đường thẳng song song</h2><p>Hai đường thẳng đồng phẳng, không có điểm chung gọi là song song.</p><p>Trong không gian, hai đường thẳng không đồng phẳng gọi là chéo nhau.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2), CAST(N''2026-10-24T11:30:09.3016456'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (6, 2, 1, 5, N''[TEST] K01 - Chương 1 – Hàm số lượng giác - Lý thuyết'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 1 – Hàm số lượng giác</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Hàm sin và cos có tập giá trị [-1;1], chu kỳ 2π. Với y = 3 sin x + 2, giá trị lớn nhất là 5 và nhỏ nhất là -1. Hãy tìm tập giá trị của y = 2 cos x - 1.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-28T14:53:16.1792651'' AS DateTime2), CAST(N''2026-10-28T14:53:16.1792651'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (7, 2, 2, 5, N''[TEST] K01 - Chương 2 – Dãy số - Lý thuyết'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 2 – Dãy số</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Cấp số cộng có uₙ = u₁ + (n-1)d. Nếu u₁ = 3, d = 3 thì u₁₀ = 30. Hãy tự tính u₂₀ và tổng 20 số hạng đầu.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-28T14:53:16.2408744'' AS DateTime2), CAST(N''2026-10-28T14:53:16.2408744'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (8, 2, 3, 5, N''[TEST] K01 - Chương 3 – Giới hạn - Lý thuyết'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 3 – Giới hạn</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Ta có (3n+2)/n = 3 + 2/n. Vì lim 1/n = 0 nên giới hạn bằng 3. Hãy tính lim (5n-7)/n và giải thích các bước.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-28T14:53:16.2448816'' AS DateTime2), CAST(N''2026-10-28T14:53:16.2448816'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (9, 2, 4, 5, N''[TEST] K01 - Chương 4 – Đường thẳng và mặt phẳng - Lý thuyết'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 4 – Đường thẳng và mặt phẳng</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Qua ba điểm không thẳng hàng xác định duy nhất một mặt phẳng. Nếu hai điểm phân biệt của đường thẳng nằm trên mặt phẳng thì cả đường thẳng nằm trên mặt phẳng. Hãy áp dụng để tìm giao tuyến hai mặt phẳng của hình chóp S.ABCD.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-28T14:53:16.2495357'' AS DateTime2), CAST(N''2026-10-28T14:53:16.2495357'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (10, 2, 5, 5, N''[TEST] K01 - Chương 5 – Quan hệ song song - Lý thuyết'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 5 – Quan hệ song song</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Trong tam giác ABC, M và N là trung điểm AB và AC thì MN song song BC và MN = BC/2. Nếu BC = 12 cm thì MN = 6 cm. Hãy chứng minh bằng định lý đường trung bình.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-28T14:53:16.2540944'' AS DateTime2), CAST(N''2026-10-28T14:53:16.2540944'' AS DateTime2))
