INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (21, 3, 1, 5, N''[TEST] K02 - Chương 1 – Hàm số lượng giác - Luyện tập'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 1 – Hàm số lượng giác</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Hàm sin và cos có tập giá trị [-1;1], chu kỳ 2π. Với y = 3 sin x + 2, giá trị lớn nhất là 5 và nhỏ nhất là -1. Hãy tìm tập giá trị của y = 2 cos x - 1.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-28T14:53:17.3809634'' AS DateTime2), CAST(N''2026-10-28T14:53:17.3809634'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (22, 3, 2, 5, N''[TEST] K02 - Chương 2 – Dãy số - Luyện tập'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 2 – Dãy số</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Cấp số cộng có uₙ = u₁ + (n-1)d. Nếu u₁ = 9, d = 3 thì u₁₀ = 36. Hãy tự tính u₂₀ và tổng 20 số hạng đầu.</p>'', N''YOUTUBE'', N''https://www.youtube.com/watch?v=NybHckSEQBI'', 1200, 1, 0, CAST(N''2026-10-28T14:53:17.3829703'' AS DateTime2), CAST(N''2026-10-28T14:53:17.3829703'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (23, 3, 3, 5, N''[TEST] K02 - Chương 3 – Giới hạn - Luyện tập'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 3 – Giới hạn</h2>
<p>Mục tiêu: nhận biết khái niệm, giải thích công thức và vận dụng qua ví dụ.</p>
<h3>Kiến thức và ví dụ</h3>
<p>Ta có (3n+2)/n = 3 + 2/n. Vì lim 1/n = 0 nên giới hạn bằng 3. Hãy tính lim (5n-7)/n và giải thích các bước.</p>'', N''TEXT'', N'''', 1200, 1, 0, CAST(N''2026-10-28T14:53:17.3849696'' AS DateTime2), CAST(N''2026-10-28T14:53:17.3849696'' AS DateTime2))
INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (24, 3, 4, 5, N''[TEST] K02 - Chương 4 – Đường thẳng và mặt phẳng - Luyện tập'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 4 – Đường thẳng và mặt phẳng</h2>
