INSERT [dbo].[lessons] ([id], [course_id], [chapter_id], [author_id], [title], [description], [objectives], [content], [content_type], [video_url], [duration_seconds], [published], [deleted], [updated_at], [created_at]) VALUES (70, 8, 5, 2, N''[TEST] K07 - Chương 5 – Quan hệ song song - Lý thuyết'', N''Bài học kiểm thử có nội dung văn bản, công thức và bài tập vận dụng.'', N''Hiểu kiến thức và trình bày lời giải rõ ràng.'', N''<h2>Chương 5 – Quan hệ song song</h2>
