INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (29, 5, 3, 5, N''[TEST] K01 - Giới hạn của dãy số 22'', N''<p>Tính giới hạn của (24n + 3)/n khi n tiến tới dương vô cùng. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Chia cho n được 24 + 3/n. Vì 1/n tiến tới 0, giới hạn là 24.'', 0, CAST(N''2026-10-28T14:53:16.6030495'' AS DateTime2), 2, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (30, 5, 4, 6, N''[TEST] K01 - Đếm đường thẳng trong mặt phẳng 23'', N''<p>Cho 7 điểm trong một mặt phẳng, không có ba điểm thẳng hàng. Có bao nhiêu đường thẳng đi qua các cặp điểm? Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Mỗi cặp điểm xác định một đường thẳng và không trùng nhau. C(7,2) = 7 × 6 / 2 = 21.'', 0, CAST(N''2026-10-28T14:53:16.6100132'' AS DateTime2), 2, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (31, 5, 5, 7, N''[TEST] K01 - Đường trung bình và quan hệ song song 24'', N''<p>Trong tam giác ABC, M và N lần lượt là trung điểm AB và AC. Biết BC = 62 cm. Tính MN (cm). Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Theo định lý đường trung bình, MN song song BC và MN = BC/2 = 31 cm.'', 0, CAST(N''2026-10-28T14:53:16.6175330'' AS DateTime2), 2, 0)
