INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (74, 6, 1, 2, N''[TEST] K03 - Giá trị lớn nhất của hàm lượng giác 19'', N''<p>Tìm giá trị lớn nhất của y = 23 sin x + 4. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Vì -1 ≤ sin x ≤ 1 và 23 &gt; 0, giá trị lớn nhất là 23 + 4 = 27.'', 0, CAST(N''2026-10-28T14:53:18.2896376'' AS DateTime2), 4, 1)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (75, 6, 2, 3, N''[TEST] K03 - Số hạng của cấp số cộng 20'', N''<p>Cấp số cộng có u₁ = 24, công sai d = 5. Tính u9. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''uₙ = u₁ + (n-1)d, nên u9 = 24 + 8 × 5 = 64.'', 0, CAST(N''2026-10-28T14:53:18.2940937'' AS DateTime2), 4, 1)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (76, 6, 2, 4, N''[TEST] K03 - Số hạng của cấp số nhân 21'', N''<p>Cấp số nhân có u₁ = 25, công bội q = 2. Tính u5. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''uₙ = u₁ × q^(n-1), nên u5 = 25 × 2^4 = 400.'', 0, CAST(N''2026-10-28T14:53:18.2990934'' AS DateTime2), 4, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (77, 6, 3, 5, N''[TEST] K03 - Giới hạn của dãy số 22'', N''<p>Tính giới hạn của (26n + 3)/n khi n tiến tới dương vô cùng. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Chia cho n được 26 + 3/n. Vì 1/n tiến tới 0, giới hạn là 26.'', 0, CAST(N''2026-10-28T14:53:18.3029191'' AS DateTime2), 4, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (78, 6, 4, 6, N''[TEST] K03 - Đếm đường thẳng trong mặt phẳng 23'', N''<p>Cho 7 điểm trong một mặt phẳng, không có ba điểm thẳng hàng. Có bao nhiêu đường thẳng đi qua các cặp điểm? Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Mỗi cặp điểm xác định một đường thẳng và không trùng nhau. C(7,2) = 7 × 6 / 2 = 21.'', 0, CAST(N''2026-10-28T14:53:18.3052013'' AS DateTime2), 4, 0)
