INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (98, 6, 1, 2, N''[TEST] K04 - Giá trị lớn nhất của hàm lượng giác 19'', N''<p>Tìm giá trị lớn nhất của y = 24 sin x + 4. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Vì -1 ≤ sin x ≤ 1 và 24 &gt; 0, giá trị lớn nhất là 24 + 4 = 28.'', 0, CAST(N''2026-10-28T14:53:19.1987197'' AS DateTime2), 5, 1)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (99, 6, 2, 3, N''[TEST] K04 - Số hạng của cấp số cộng 20'', N''<p>Cấp số cộng có u₁ = 25, công sai d = 5. Tính u9. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''uₙ = u₁ + (n-1)d, nên u9 = 25 + 8 × 5 = 65.'', 0, CAST(N''2026-10-28T14:53:19.2042105'' AS DateTime2), 5, 1)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (100, 6, 2, 4, N''[TEST] K04 - Số hạng của cấp số nhân 21'', N''<p>Cấp số nhân có u₁ = 26, công bội q = 2. Tính u5. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''uₙ = u₁ × q^(n-1), nên u5 = 26 × 2^4 = 416.'', 0, CAST(N''2026-10-28T14:53:19.2058198'' AS DateTime2), 5, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (101, 6, 3, 5, N''[TEST] K04 - Giới hạn của dãy số 22'', N''<p>Tính giới hạn của (27n + 3)/n khi n tiến tới dương vô cùng. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Chia cho n được 27 + 3/n. Vì 1/n tiến tới 0, giới hạn là 27.'', 0, CAST(N''2026-10-28T14:53:19.2120383'' AS DateTime2), 5, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (102, 6, 4, 6, N''[TEST] K04 - Đếm đường thẳng trong mặt phẳng 23'', N''<p>Cho 7 điểm trong một mặt phẳng, không có ba điểm thẳng hàng. Có bao nhiêu đường thẳng đi qua các cặp điểm? Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Mỗi cặp điểm xác định một đường thẳng và không trùng nhau. C(7,2) = 7 × 6 / 2 = 21.'', 0, CAST(N''2026-10-28T14:53:19.2148805'' AS DateTime2), 5, 0)
