INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (146, 7, 1, 2, N''[TEST] K06 - Giá trị lớn nhất của hàm lượng giác 19'', N''<p>Tìm giá trị lớn nhất của y = 26 sin x + 4. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Vì -1 ≤ sin x ≤ 1 và 26 &gt; 0, giá trị lớn nhất là 26 + 4 = 30.'', 0, CAST(N''2026-10-28T14:53:20.8517294'' AS DateTime2), 7, 1)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (147, 7, 2, 3, N''[TEST] K06 - Số hạng của cấp số cộng 20'', N''<p>Cấp số cộng có u₁ = 27, công sai d = 5. Tính u9. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''uₙ = u₁ + (n-1)d, nên u9 = 27 + 8 × 5 = 67.'', 0, CAST(N''2026-10-28T14:53:20.8587995'' AS DateTime2), 7, 1)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (148, 7, 2, 4, N''[TEST] K06 - Số hạng của cấp số nhân 21'', N''<p>Cấp số nhân có u₁ = 28, công bội q = 2. Tính u5. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''uₙ = u₁ × q^(n-1), nên u5 = 28 × 2^4 = 448.'', 0, CAST(N''2026-10-28T14:53:20.8607099'' AS DateTime2), 7, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (149, 7, 3, 5, N''[TEST] K06 - Giới hạn của dãy số 22'', N''<p>Tính giới hạn của (29n + 3)/n khi n tiến tới dương vô cùng. Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Chia cho n được 29 + 3/n. Vì 1/n tiến tới 0, giới hạn là 29.'', 0, CAST(N''2026-10-28T14:53:20.8657775'' AS DateTime2), 7, 0)
INSERT [dbo].[questions] ([id], [author_id], [chapter_id], [topic_id], [title], [content], [type], [difficulty], [cognitive_level], [answer], [deleted], [created_at], [course_id], [published]) VALUES (150, 7, 4, 6, N''[TEST] K06 - Đếm đường thẳng trong mặt phẳng 23'', N''<p>Cho 7 điểm trong một mặt phẳng, không có ba điểm thẳng hàng. Có bao nhiêu đường thẳng đi qua các cặp điểm? Trình bày các bước giải.</p>'', N''ESSAY'', N''EASY'', N''KNOWLEDGE'', N''Mỗi cặp điểm xác định một đường thẳng và không trùng nhau. C(7,2) = 7 × 6 / 2 = 21.'', 0, CAST(N''2026-10-28T14:53:20.8657775'' AS DateTime2), 7, 0)
